         .stdout(predicate::eq("pager-output\n").normalize());
 }

+#[test]
+#[serial]
+fn pager_plain_preserves_paging_and_style() {
+    mocked_pagers::with_mocked_versions_of_more_and_most_in_path(|| {
+        for plain in ["-p", "--plain"] {
+            for paging in ["--paging=always", "--paging=never"] {
+                for args in [[plain, paging], [paging, plain]] {
+                    bat()
+                        .env("BAT_PAGER", mocked_pagers::from("echo pager-output"))
+                        .args(["--color=never", "--decorations=always", "--style=numbers"])
+                        .args(args)
+                        .arg("test.txt")
+                        .assert()
+                        .success()
+                        .stdout(
+                            predicate::eq(if paging == "--paging=always" {
+                                "pager-output\n"
+                            } else {
+                                "hello world\n"
+                            })
+                            .normalize(),
+                        );
+                }
+            }
+        }
+    });
+}
+
+#[cfg(unix)]
+#[test]
+fn pager_plain_paging_precedence_with_interactive_output() {
+    // A terminal is needed to distinguish automatic paging from disabled paging.
+    for plain in [vec!["-p"], vec!["--plain"], vec!["-pp"], vec!["--plain", "--plain"]] {
+        for paging in ["--paging=never", "--paging=auto"] {
+            for plain_last in [false, true] {
+                let OpenptyResult { master: _master, slave } =
+                    openpty(None, None).expect("Couldn't open pty.");
+                let mut command = bat_raw_command();
+                command
+                    .arg("--pager=bat")
+                    .arg("--color=never")
+                    .stdout(Stdio::from(File::from(slave)));
+                if plain_last {
+                    command.arg(paging).args(&plain);
+                } else {
+                    command.args(&plain).arg(paging);
+                }
+                let assertion = command.arg("test.txt").assert();
+                let double_plain = plain == ["-pp"] || plain.len() > 1;
+                if paging == "--paging=never" || (double_plain && plain_last) {
+                    assertion.success().stderr("");
+                } else {
+                    assertion
+                        .failure()
+                        .stderr(predicate::str::contains("bat as a pager is disallowed"));
+                }
+            }
+        }
+    }
+}
+
+#[test]
+fn pager_plain_long_double_disables_paging() {
+    bat()
+        .env("BAT_PAGER", "echo pager-output")
+        .arg("--paging=always")
+        .arg("--plain")
+        .arg("--plain")
+        .arg("test.txt")
+        .assert()
+        .success()
+        .stdout(predicate::eq("hello world\n").normalize());
+}
